 a=[x['data'][k] for x in m if k in x['data']];print(k,'range',min(a),max(a),'first10',statistics.mean(a[:10]),'last10',statistics.mean(a[-10:]))
for f in sorted(glob.glob(p+'val_generations/*'),key=lambda s:int(s.split('/')[-1].split('.')[0])):
 a=[json.loads(l) for l in open(f)];print(f,len(a),sum(x['score'] for x in a), 'hashformat',sum('####' in x['output'] for x in a),'chars',round(statistics.mean(len(x['output']) for x in a)))
print('rollout example',open(p+'rollouts/60.jsonl').readline()[:2500])
